<!-- This file is generated by AI. -->

<!--
  项目编辑页: 顶栏 + 左侧(预览 + 场景/资源) + 右侧(选项卡/编辑区/状态栏)。

  几个刻意保留的细节:

  * 项目名占据左侧栏与右侧按钮之间的**全部空档**: 短名不留空白, 长名才被省略号截断;
  * 侧栏宽度可拖拽 (下限 280, 上限 760 且不挤掉编辑区), 拖拽时给 `body` 加 `.resizing`
    以禁用全局的文本选择与 iframe 指针事件;
  * 侧栏折叠后留一个细长的展开按钮, 而不是彻底消失 (否则没法再打开)。

  项目级初始化 (git 状态与监听) 也在这里: 它们只在打开项目之后才有意义。
-->

<script lang="ts">
  import { onMount } from 'svelte';

  import { refreshGitStatus, startGitWatcher, stopGitWatcher } from '../git/status';
  import { closeProject } from '../project';
  import { makeNovelTab } from '../tabs/model';
  import {
    activeConfigDocumentOf,
    activeResourceDocumentOf,
    activeSceneDocumentOf,
    activeTabOf,
  } from '../state/selectors';
  import { actions, appStore } from '../state/store.svelte';
  import { confirmClose } from '../unsaved';
  import { toggleVoiceWorkbench, voiceWorkbenchOpen } from '../voice/mode';
  import Button from './Button.svelte';
  import CodeEditor from './CodeEditor.svelte';
  import Diagnostics from './Diagnostics.svelte';
  import type { FileTreeViewStateCache } from './FileTree.svelte';
  import GitDiffEditor from './GitDiffEditor.svelte';
  import PreprocessTab from './PreprocessTab.svelte';
  import Spinner from './Spinner.svelte';
  import VoiceWorkbench from './VoiceWorkbench.svelte';
  import PreviewPanel from './PreviewPanel.svelte';
  import ProjectTab from './ProjectTab.svelte';
  import RepositoryTab from './RepositoryTab.svelte';
  import ResourceBrowser from './ResourceBrowser.svelte';
  import ResourceTab from './ResourceTab.svelte';
  import SceneBrowser from './SceneBrowser.svelte';
  import SceneVoiceEditor from './SceneVoiceEditor.svelte';
  import SnapshotDialog from './SnapshotDialog.svelte';
  import StatusBar from './StatusBar.svelte';
  import VoiceGuidePane from './VoiceGuidePane.svelte';
  import TabStrip from './TabStrip.svelte';

  type SidebarTab = 'scenes' | 'resources' | 'project' | 'repository';

  const MIN_SIDEBAR = 280;
  const MAX_SIDEBAR = 760;

  let sidebarVisible = $state(true);
  let sidebarTab = $state<SidebarTab>('scenes');
  let sidebarWidth = $state(480);
  let resizing = $state(false);
  /** 一次"定位到左侧浏览器"的请求 (由选项卡栏右键菜单发起)。 */
  let revealRequest = $state<{ id: number; path: string } | null>(null);
  let revealSequence = 0;
  /** 文本预处理选项卡的序号 (只用于标题里的编号, 选项卡本身不是单例)。 */
  let novelSequence = 0;
  /** 快照打包对话框 */
  let snapshotOpen = $state(false);

  /*
   * 文件树的视图状态缓存。
   *
   * 放在编辑页而不是文件树内部: 侧栏切页时组件会卸载, 内部状态留不住; 而用户期望
   * "切到资源看一眼再切回场景"仍然停在原来的目录与滚动位置。缓存是普通 Map, 因此
   * 不需要响应式 —— 它只在挂载时被读一次。
   */
  const sidebarViewState: FileTreeViewStateCache = new Map();

  const projectPath = $derived(appStore.projectPath);
  const projectName = $derived(appStore.projectName);
  const activeTab = $derived(activeTabOf(appStore));
  const sceneDoc = $derived(activeSceneDocumentOf(appStore));
  const configDoc = $derived(activeConfigDocumentOf(appStore));
  const resourceDoc = $derived(activeResourceDocumentOf(appStore));
  /**
   * 当前场景是否处于配音编辑模式 —— 决定用配音卡还是普通编辑器。
   *
   * 模式由 store 的 `voiceModePaths` 定义 (进入/退出只有一个入口: 选项卡上的麦克风)。
   */
  const sceneInVoiceMode = $derived(Boolean(sceneDoc && appStore.voiceModePaths.includes(sceneDoc.path)));
  /**
   * 配音工作台是否已经打开 —— 决定顶栏那个麦克风按钮是强调态还是普通态。
   *
   * `voiceWorkbenchOpen()` 读的是 store, 放在 `$derived` 里就有响应性。
   */
  const workbenchOpen = $derived(voiceWorkbenchOpen());
  const voiceStarting = $derived(appStore.voiceStatus === 'starting');

  // 项目打开时拉一次 git 状态, 并起文件监听做防抖刷新。
  onMount(() => {
    const path = projectPath;
    if (!path) return;
    void refreshGitStatus(path);
    void startGitWatcher(path);
    return () => {
      void stopGitWatcher();
    };
  });

  /** 开始拖拽分隔条 (指针捕获, 移动时调整侧栏宽度)。 */
  function onResizeStart(event: PointerEvent & { currentTarget: HTMLDivElement }) {
    event.preventDefault();
    event.currentTarget.setPointerCapture(event.pointerId);
    resizing = true;
    document.body.classList.add('resizing');
  }

  function onResizeMove(event: PointerEvent) {
    if (!resizing) return;
    const max = Math.min(MAX_SIDEBAR, Math.max(MIN_SIDEBAR, window.innerWidth - 320));
    sidebarWidth = Math.min(Math.max(event.clientX, MIN_SIDEBAR), max);
  }

  function onResizeEnd() {
    resizing = false;
    document.body.classList.remove('resizing');
  }

  /**
   * 把当前选项卡定位到左侧浏览器 (入口在选项卡栏的右键菜单里)。
   *
   * 先切到对应的侧栏页并展开侧栏 —— 文件树的定位 effect 会在挂载时消费这个请求,
   * 因此顺序不能反 (先请求再切页的话, 新挂载的实例会看到它)。
   */
  function locateTab(path: string, kind: 'scene' | 'resource' | 'config') {
    sidebarVisible = true;

    /*
     * 配置卡没有自己的浏览器页 —— 它归「项目」页。因此 config 只切页、**不发定位请求**:
     * 项目页是配置摘要而不是文件列表, 发过去也没有能消费它的文件树, 请求会一直挂着。
     */
    if (kind === 'config') {
      sidebarTab = 'project';
      return;
    }

    sidebarTab = kind === 'scene' ? 'scenes' : 'resources';
    revealSequence += 1;
    revealRequest = { id: revealSequence, path };
  }
</script>

<div class="editor-page">
  <div class="top-bar">
    <!--
      顶栏这几个按钮都是"只有图标"的工具栏按钮, 因此用 `bare` (无边框 + 悬浮底色 + 30px
      命中区, 见 styles.css 里 `.ui-button-bare` 的说明)。`subtle` 在本项目里映射的是
      **有边框**的 `.ui-button`, 用在这里会让整排按钮看起来像一排方块。
    -->
    <Button
      appearance="bare"
      icon="ArrowLeft"
      iconSize={20}
      title="关闭项目"
      onclick={() => confirmClose(() => void closeProject())}
    />
    <span class="project-name" title={projectName ?? '未命名项目'}>{projectName ?? '未命名项目'}</span>
    <Button
      appearance="bare"
      icon="DocumentText"
      iconSize={20}
      title="文本预处理"
      onclick={() => actions.addNovelTab(makeNovelTab(++novelSequence))}
    />
    {#if voiceStarting}
      <!-- 启动中: 图标换成加载圈, 并且保留同一个按钮 (点它仍可打开/聚焦工作台看进度) -->
      <Button
        appearance={workbenchOpen ? 'primary' : 'bare'}
        title="配音服务启动中…"
        onclick={() => toggleVoiceWorkbench()}
      >
        <Spinner size={16} label="配音服务启动中" />
      </Button>
    {:else}
      <Button
        appearance={workbenchOpen ? 'primary' : 'bare'}
        icon="Mic"
        iconSize={20}
        title={workbenchOpen ? '关闭配音工作台' : '打开配音工作台'}
        onclick={() => toggleVoiceWorkbench()}
      />
    {/if}
    <!--
      生成快照前先处理未保存的更改: 打包读的是**磁盘上的文件**, 刚敲的改动如果不落盘就不会
      进包 —— 而且没有任何提示, 用户会以为"我明明写了"。
    -->
    <Button
      appearance="bare"
      icon="Archive"
      iconSize={20}
      title="生成快照"
      onclick={() => confirmClose(() => (snapshotOpen = true), undefined, '生成快照前是否保存未保存的更改？')}
    />
  </div>

  <div class="editor-main">
    {#if sidebarVisible}
      <div class="sidebar" style="width:{sidebarWidth}px">
        <div class="sidebar-preview">
          <PreviewPanel />
        </div>

        <div class="sidebar-tabs">
          <button class:active={sidebarTab === 'project'} onclick={() => (sidebarTab = 'project')}>项目</button>
          <button class:active={sidebarTab === 'repository'} onclick={() => (sidebarTab = 'repository')}>仓库</button>
          <button class:active={sidebarTab === 'scenes'} onclick={() => (sidebarTab = 'scenes')}>场景</button>
          <button class:active={sidebarTab === 'resources'} onclick={() => (sidebarTab = 'resources')}>资源</button>
          <button class="sidebar-collapse" title="折叠侧栏" onclick={() => (sidebarVisible = false)}>
            <span class="sidebar-collapse-glyph">‹</span>
          </button>
        </div>

        <div class="sidebar-content">
          {#if sidebarTab === 'scenes'}
            <SceneBrowser
              viewStateCache={sidebarViewState}
              viewStateKey="scenes"
              {revealRequest}
              onRevealComplete={(id) => {
                if (revealRequest?.id === id) revealRequest = null;
              }}
            />
          {:else if sidebarTab === 'resources'}
            <ResourceBrowser
              viewStateCache={sidebarViewState}
              viewStateKey="resources"
              {revealRequest}
              onRevealComplete={(id) => {
                if (revealRequest?.id === id) revealRequest = null;
              }}
            />
          {:else if sidebarTab === 'project'}
            <ProjectTab />
          {:else}
            <RepositoryTab />
          {/if}
        </div>
      </div>

      <div
        class="sidebar-resizer"
        class:active={resizing}
        title="拖拽调整侧栏宽度"
        role="separator"
        aria-orientation="vertical"
        onpointerdown={onResizeStart}
        onpointermove={onResizeMove}
        onpointerup={onResizeEnd}
        onpointercancel={onResizeEnd}
      ></div>
    {:else}
      <button class="sidebar-expand" title="展开侧栏" onclick={() => (sidebarVisible = true)}>
        <span class="sidebar-expand-glyph">›</span>
      </button>
    {/if}

    <div class="editor-workspace">
      <TabStrip onLocateTab={locateTab} />
      <div class="editor-area">
        {#if activeTab?.kind === 'scene'}
          {#if sceneDoc}
            {#if sceneInVoiceMode}
              <!-- 配音编辑模式: 编辑器旁多出"当前对话 + 历史"的面板 -->
              <SceneVoiceEditor docPath={sceneDoc.path} />
            {:else}
              <CodeEditor doc={sceneDoc} />
            {/if}
          {:else}
            <div class="editor-empty">正在读取场景…</div>
          {/if}
        {:else if activeTab?.kind === 'config'}
          {#if configDoc}
            <CodeEditor doc={configDoc} />
          {:else}
            <div class="editor-empty">正在读取项目配置…</div>
          {/if}
        {:else if activeTab?.kind === 'resource'}
          <ResourceTab tab={activeTab} doc={resourceDoc} />
        {:else if activeTab?.kind === 'diff'}
          <GitDiffEditor tab={activeTab} />
        {:else if activeTab?.kind === 'novel'}
          <!--
            `{#key}` 是**必须的**, 不是优化: 预处理组件在顶层只求值一次
            `getOrCreateSession(id, ...)` / `novelModelUri(id)`。不 key 的话, 从"小说 A"切到
            "小说 B"时组件实例被复用, 里面仍指向 A 的会话 —— 编辑器会显示另一个选项卡的文本。
            key 掉之后换选项卡就是新实例; 会话本身仍留在 registry 里 (预处理会话与"切走再切回
            恢复同一步"的前提都靠它)。
          -->
          {#key activeTab.id}
            <PreprocessTab id={activeTab.id} />
          {/key}
        {:else if activeTab?.kind === 'voice-workbench'}
          <VoiceWorkbench />
        {:else if activeTab?.kind === 'guidance'}
          <VoiceGuidePane />
        {:else}
          <!--
            兜底: 一个活动选项卡都没有, 或者将来新增了 kind 却还没接上界面 —— 后者给一句明确的
            话而不是留空白。
          -->
          <div class="editor-empty">
            {activeTab ? '这个选项卡暂时没有可显示的内容' : '从左侧选择或打开一个场景开始编辑'}
          </div>
        {/if}
      </div>

      <!--
        诊断列表: 弹窗盖住编辑区, 托盘从底部升起 (不遮挡代码, 适合"点一条改一条")。
        两种形式共用同一份实现, 只有外壳不同 —— 见 Diagnostics.svelte。
      -->
      {#if appStore.diagnosticsOpen && appStore.settings.diagnosticsView === 'dock'}
        <Diagnostics variant="dock" onClose={() => actions.setDiagnosticsOpen(false)} />
      {/if}

      <StatusBar />
    </div>
  </div>

  {#if snapshotOpen}
    <SnapshotDialog onClose={() => (snapshotOpen = false)} />
  {/if}

  {#if appStore.diagnosticsOpen && appStore.settings.diagnosticsView === 'modal'}
    <Diagnostics variant="modal" onClose={() => actions.setDiagnosticsOpen(false)} />
  {/if}
</div>
